def clamp(v):
    if v < -1.0:
        return -1.0
    if v > 1.0:
        return 1.0
    return v

def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)

    d = distance_to(enemy.x, enemy.y)
    b = bearing_to(enemy.x, enemy.y)

    if "side" not in me.memory:
        ll = enemy.armor.get("left", 1.0)
        rr = enemy.armor.get("right", 1.0)
        if ll < rr:
            side = 1.0
        else:
            side = -1.0
        me.memory["side"] = side
    else:
        side = me.memory.get("side", 1.0)

    target = 0.0
    if d < 1.8:
        target = 20.0 * side
        if d < 0.8:
            target = 45.0 * side

    r = hypot(me.x, me.y)
    if r > arena.radius - 1.0:
        bc = bearing_to(0.0, 0.0)
        if abs(bc) > 20.0:
            target = bc

    err = target - b
    if err > 180.0:
        err -= 360.0
    elif err < -180.0:
        err += 360.0

    steer = clamp(err / 35.0)

    if d > 2.2:
        fwd = 1.0
    elif d > 1.2:
        fwd = 0.8
    elif d > 0.8:
        fwd = 0.45
    else:
        fwd = -0.55

    if r > arena.radius - 0.7:
        fwd = 0.5
    if abs(steer) > 0.75:
        fwd = fwd * 0.5

    left = clamp(fwd - 0.9 * steer)
    right = clamp(fwd + 0.9 * steer)
    return (left, right)

